  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "The closest analogue (Molecule 1, Morgan 0.4359) shares the thiophene-sulfonyl-isoxazole core and showed >80% oral availability in humans in phase I development.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Tiagabine, a thiophene-containing drug, has absolute oral bioavailability of about 90% in humans, supporting high F for thiophene-containing structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir, a heteroaryl sulfonamide, showed 75% bioavailability after a single 100 mg oral dose in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Stiripentol, which contains the same benzodioxole ring as the query, has human oral bioavailability ≥90% (absolute).",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Medroxalol, another benzodioxole-containing drug, had absolute oral bioavailability 37.4% at 1200 mg, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Sulfamethoxazole, a sulfonamide-isoxazole, has human oral bioavailability >80%, supporting the sulfonamide-isoxazole motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Azosemide, a more polar sulfonamide/tetrazole/thiophene drug, had only ~10% bioavailability, but its low structural transferability limits its contradiction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%) based on multiple structurally related sulfonamide/isoxazole and benzodioxole-containing drugs with human oral bioavailability mostly >70%, with only a low-similarity azosemide counterexample.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule; prediction relies on structural analogues.",
    "Morgan similarities are moderate (0.18–0.44), so quantitative F transfer is uncertain.",
    "No data on solubility, permeability, or first-pass metabolism for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

